thread_local bool g_jit_stable_guest_reads = false;

// Keep every guest-visible TSC source in the same architectural counter domain used by
// Common::NativeClock on AArch64 (CNTVCT_EL0).  RDTSC is intentionally not a load fence; RDTSCP
// waits for older loads, but not stores, exactly as the x86 contract and FEX lowering require.
// This distinction matters to lock-free timing probes even though most games use the pair only
// for profiling.
std::uint64_t ReadGuestTsc(const bool prior_loads_visible) {
#if defined(__aarch64__)
    std::uint64_t value = 0;
    if (prior_loads_visible) {
        asm volatile("dmb ishld\n\t"
                     "mrs %0, cntvct_el0"
                     : "=r"(value)
                     :
                     : "memory");
    } else {
        asm volatile("mrs %0, cntvct_el0" : "=r"(value));
    }
    return value;
#else
    // JIT is an AArch64 backend, but retain a monotonic fallback for host-side tests.
    return static_cast<std::uint64_t>(
        std::chrono::steady_clock::now().time_since_epoch().count());
#endif
}

std::uint32_t ReadGuestTscAux() {
#ifdef __ANDROID__
    // Match FEX: IA32_TSC_AUX is Linux's NUMA-node/CPU identity, not a title-specific constant.
    // Android exposes getcpu through the kernel even when libc does not expose sched_getcpu().
    unsigned cpu = 0;
    unsigned node = 0;
    if (syscall(SYS_getcpu, &cpu, &node, nullptr) == 0) {
        return (node << 12u) | cpu;
    }
    std::uint64_t tpidrro = 0;
    asm volatile("mrs %0, tpidrro_el0" : "=r"(tpidrro));
    return static_cast<std::uint32_t>(tpidrro);
#else
    return 0;
#endif
}

// X86 exposes the decoded displacement value together with its encoded width.  Persistent IR
// and a few decoder versions may retain only the raw low bits in `value`; relying on the C++
// field's apparent signedness consequently turns disp8/disp32 stack references into large
// positive offsets.  Canonicalize from the architectural encoded width at every effective-address
// boundary.  This matches x86-64 ModRM/SIB sign extension and is shared by helper and native paths.
std::int64_t SignedMemoryDisplacement(const LsxOperandRecord& operand) {
    const std::uint32_t bits = operand.mem.disp.size;
    std::uint64_t raw = static_cast<std::uint64_t>(operand.mem.disp.value);
    if (bits == 0 || bits >= 64) {
        return std::bit_cast<std::int64_t>(raw);
    }
    if (bits != 8 && bits != 16 && bits != 32) {
        return static_cast<std::int64_t>(operand.mem.disp.value);
    }
    const std::uint64_t mask = (std::uint64_t{1} << bits) - 1;
    const std::uint64_t sign = std::uint64_t{1} << (bits - 1);
    raw &= mask;
    const std::uint64_t extended = (raw ^ sign) - sign;
    return std::bit_cast<std::int64_t>(extended);
}

bool IsJitScalarFloatAddSubMulMnemonic(const X86Mnemonic mnemonic) {
    switch (mnemonic) {
    case X86_MNEMONIC_ADDSS:
    case X86_MNEMONIC_SUBSS:
    case X86_MNEMONIC_MULSS:
    case X86_MNEMONIC_VADDSS:
    case X86_MNEMONIC_VSUBSS:
    case X86_MNEMONIC_VMULSS:
        return true;
    default:
        return false;
    }
}

bool JitBlockUsesScalarFloatAddSubMul(const LsxDecodedRegion& block) {
    return std::ranges::any_of(block.instructions, [](const LsxDecodedOp& ir) {
        return IsJitScalarFloatAddSubMulMnemonic(
            static_cast<X86Mnemonic>(ir.mnemonic));
    });
}

