            code->mov(code->x16, code->x11);
            code->L(rcx_ready);
            code->str(code->x16,
                      Xbyak_aarch64::ptr(code->x19, kStateRcxOffset));
            code->mov(code->x14, ~std::uint64_t{0xff});
            code->and_(code->x13, code->x13, code->x14);
            code->orr(code->x13, code->x13, code->x15);
            code->str(code->x13,
                      Xbyak_aarch64::ptr(code->x19, kStateR10Offset));

            code->ldr(code->x17,
                      Xbyak_aarch64::ptr(code->x19, kStateR8Offset));
            code->adds(code->x17, code->x17, 0x20);
            code->cset(code->x20, Xbyak_aarch64::CS);
            code->str(code->x17,
                      Xbyak_aarch64::ptr(code->x19, kStateR8Offset));
            code->ldr(code->w9,
                      Xbyak_aarch64::ptr(code->x19, kStateR9Offset));
            code->add(code->w11, code->w9, 1);
            code->str(code->x11,
                      Xbyak_aarch64::ptr(code->x19, kStateR9Offset));
            code->mov(code->x0, code->x19);
            code->mov(code->x1, code->x9);
            code->mov(code->x2, 1);
            code->mov(code->x3, code->x11);
            code->mov(code->x4, 32);
            EmitJitRelocatablePointer(
                *code, code->x16, reinterpret_cast<std::uint64_t>(&CommitAddFlags));
            code->blr(code->x16);
            code->ldr(code->x9,
                      Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));
            code->mov(code->x10, ~std::uint64_t{1});
