    // Sonic Mania's steady-state RGB565 blend loop.  This was the largest helper left after
    // the row-copy and packed-pixel families were lowered.  Match the complete 146-byte shape,
    // but derive both the RIP-relative palette base and the JNE target from the decoded block so
    // the generated code is independent of Sonic's load address.  Every architectural register
    // write is committed before the next guest memory access, and the flags live at each possible
    // synchronous fault are published before that access.  The reads and final word store remain
    // in x86 order, which is important when the destination aliases the source texture.
    static constexpr std::array<std::uint8_t, 146> kRgb565BlendJnePattern = {
        0x4c, 0x89, 0xf0, 0x44, 0x0f, 0xb7, 0x26, 0xbb,
        0x06, 0x05, 0x00, 0x00, 0x48, 0xc1, 0xe0, 0x09,
        0x48, 0x03, 0x05, 0x42, 0xa8, 0x0f, 0x00, 0x45,
        0x89, 0xe1, 0x44, 0x0f, 0xb7, 0x1c, 0x78, 0x41,
        0x81, 0xe1, 0x00, 0xf8, 0x00, 0x00, 0xbf, 0x00,
        0xf8, 0x00, 0x00, 0x4c, 0x89, 0xd8, 0x48, 0xc1,
        0xe8, 0x0b, 0x0f, 0xb7, 0x04, 0x42, 0xc1, 0xe0,
        0x0b, 0x44, 0x01, 0xc8, 0x3d, 0x00, 0xf8, 0x00,
        0x00, 0x0f, 0x47, 0xc7, 0xc4, 0xc2, 0x60, 0xf7,
        0xdb, 0x44, 0x89, 0xe7, 0x0f, 0xb7, 0x1c, 0x5a,
        0x81, 0xe7, 0xe0, 0x07, 0x00, 0x00, 0xc1, 0xe3,
        0x06, 0x01, 0xfb, 0x81, 0xfb, 0xe0, 0x07, 0x00,
        0x00, 0x41, 0x0f, 0x47, 0xdd, 0x41, 0x83, 0xe3,
        0x1f, 0x41, 0x83, 0xe4, 0x1f, 0x09, 0xc3, 0x42,
        0x0f, 0xb7, 0x04, 0x5a, 0x44, 0x01, 0xe0, 0x83,
        0xf8, 0x1f, 0x0f, 0x47, 0xc5, 0x09, 0xd8, 0x66,
        0x89, 0x06, 0x48, 0xff, 0xc1, 0x48, 0x83, 0xc6,
        0x02, 0x45, 0x85, 0xc0, 0x0f, 0x85, 0x5f, 0xff,
        0xff, 0xff,
    };
    if (block_bytes_match(kRgb565BlendJnePattern.data(),
                          kRgb565BlendJnePattern.size()) &&
        block.instructions.size() == 37) {
        const LsxDecodedOp& rip_add = block.instructions[4];
        const LsxDecodedOp& terminator = block.instructions.back();
        std::uint64_t taken = 0;
        if (rip_add.operand_count >= 2 &&
            rip_add.operands[1].type == X86_OPERAND_TYPE_MEMORY &&
            rip_add.operands[1].mem.base == X86_REGISTER_RIP &&
            TryResolveBranchTarget(terminator, taken)) {
            const std::uint64_t palette_base_address =
                rip_add.guest_rip + rip_add.length +
                static_cast<std::uint64_t>(
                    SignedMemoryDisplacement(rip_add.operands[1]));
            const std::uint64_t fallthrough = terminator.guest_rip + terminator.length;
            auto code = std::make_unique<Xbyak_aarch64::CodeGenerator>(8192);
            Xbyak_aarch64::Label red_done;
            Xbyak_aarch64::Label green_done;
            Xbyak_aarch64::Label blue_done;
            Xbyak_aarch64::Label take;

            const auto emit_shift64_flags = [&]
                (const XReg& lhs, const XReg& result, const std::uint32_t count,
                 const bool left) {
                // Match Shift(): counts here are fixed at 9/11, so OF and AF are cleared.
                // x14 accumulates x86 CF/PF/ZF/SF; x15-x17 are scratch only.
                code->mov(code->x14, 0);
                code->lsr(code->x15, lhs, left ? 64u - count : count - 1u);
                code->mov(code->x16, 1);
                code->and_(code->x15, code->x15, code->x16);
                code->orr(code->x14, code->x14, code->x15);

                code->mov(code->w15, WReg(result.getIdx()));
                code->lsr(code->w16, code->w15, 4);
                code->eor(code->w15, code->w15, code->w16);
                code->lsr(code->w16, code->w15, 2);
                code->eor(code->w15, code->w15, code->w16);
                code->lsr(code->w16, code->w15, 1);
                code->eor(code->w15, code->w15, code->w16);
                code->mov(code->w16, 1);
                code->and_(code->w15, code->w15, code->w16);
                code->eor(code->w15, code->w15, code->w16);
                code->lsl(code->x15, code->x15, kPfBit);
                code->orr(code->x14, code->x14, code->x15);

                code->cmp(result, 0);
                code->cset(code->x15, Xbyak_aarch64::EQ);
                code->lsl(code->x15, code->x15, kZfBit);
                code->orr(code->x14, code->x14, code->x15);
                code->lsr(code->x15, result, 63);
                code->lsl(code->x15, code->x15, kSfBit);
                code->orr(code->x14, code->x14, code->x15);

                code->ldr(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
                code->mov(code->x16, kArithmeticStatusBits);
                code->bic(code->x15, code->x15, code->x16);
                code->orr(code->x15, code->x15, code->x14);
                code->str(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
            };

            // mov rax,r14 ; movzx r12d,word [rsi]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x0, kStateR14Offset));
            code->str(code->x9, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRsiOffset));
            code->ldrh(code->w11, Xbyak_aarch64::ptr(code->x10));
            code->str(code->x11, Xbyak_aarch64::ptr(code->x0, kStateR12Offset));

            // mov ebx,0x506 ; shl rax,9 ; add rax,[rip+disp32]
            code->mov(code->w12, 0x506);
            code->str(code->x12, Xbyak_aarch64::ptr(code->x0, kStateRbxOffset));
            code->mov(code->x13, code->x9);
            code->lsl(code->x9, code->x9, 9);
            code->str(code->x9, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            emit_shift64_flags(code->x13, code->x9, 9, true);
            code->mov(code->x10, palette_base_address);
            code->ldr(code->x11, Xbyak_aarch64::ptr(code->x10));
            emit_inline_add64_flags(*code, code->x9, code->x11, code->x13);
            code->str(code->x13, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));

            // mov r9d,r12d ; movzx r11d,word [rax+rdi*2]
            code->ldr(code->w12, Xbyak_aarch64::ptr(code->x0, kStateR12Offset));
            code->str(code->x12, Xbyak_aarch64::ptr(code->x0, kStateR9Offset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRdiOffset));
            code->lsl(code->x10, code->x10, 1);
            code->add(code->x10, code->x13, code->x10);
            code->ldrh(code->w9, Xbyak_aarch64::ptr(code->x10));
            code->str(code->x9, Xbyak_aarch64::ptr(code->x0, kStateR11Offset));

            // Prepare the red-channel table index. SHR's flags are live at the table read.
            code->ldr(code->w10, Xbyak_aarch64::ptr(code->x0, kStateR9Offset));
            code->mov(code->w11, 0xf800);
            code->and_(code->w10, code->w10, code->w11);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x0, kStateR9Offset));
            code->str(code->x11, Xbyak_aarch64::ptr(code->x0, kStateRdiOffset));
            code->ldr(code->x12, Xbyak_aarch64::ptr(code->x0, kStateR11Offset));
            code->str(code->x12, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            code->lsr(code->x13, code->x12, 11);
            code->str(code->x13, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            emit_shift64_flags(code->x12, code->x13, 11, false);
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x0, kStateRdxOffset));
            code->lsl(code->x10, code->x13, 1);
            code->add(code->x10, code->x9, code->x10);
            code->ldrh(code->w13, Xbyak_aarch64::ptr(code->x10));
            code->str(code->x13, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));

            // Saturating red sum and BEXTR ebx,r11d,0x506.
            code->lsl(code->w13, code->w13, 11);
            code->ldr(code->w10, Xbyak_aarch64::ptr(code->x0, kStateR9Offset));
            code->add(code->w13, code->w13, code->w10);
            code->mov(code->w11, 0xf800);
            code->cmp(code->w13, code->w11);
            code->bls(red_done);
            code->mov(code->w13, code->w11);
            code->L(red_done);
            code->str(code->x13, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x0, kStateR11Offset));
            code->ubfx(code->w10, code->w9, 6, 5);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRbxOffset));
            emit_inline_test32_flags(*code, code->w10);
            code->ldr(code->w11, Xbyak_aarch64::ptr(code->x0, kStateR12Offset));
            code->str(code->x11, Xbyak_aarch64::ptr(code->x0, kStateRdiOffset));

            // Green lookup and saturating sum.  The MOVZX load happens after BEXTR flags.
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x0, kStateRdxOffset));
            code->lsl(code->x12, code->x10, 1);
            code->add(code->x12, code->x9, code->x12);
            code->ldrh(code->w10, Xbyak_aarch64::ptr(code->x12));
            code->str(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRbxOffset));
            code->mov(code->w12, 0x7e0);
            code->and_(code->w11, code->w11, code->w12);
            code->str(code->x11, Xbyak_aarch64::ptr(code->x0, kStateRdiOffset));
            code->lsl(code->w10, code->w10, 6);
            code->add(code->w10, code->w10, code->w11);
            code->cmp(code->w10, code->w12);
            code->bls(green_done);
            code->ldr(code->w10, Xbyak_aarch64::ptr(code->x0, kStateR13Offset));
            code->L(green_done);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRbxOffset));

            // Low-channel indices and the red|green partial result. OR flags are live at the
            // final palette read, so publish them before dereferencing RDX again.
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x0, kStateR11Offset));
            code->mov(code->w12, 0x1f);
            code->and_(code->w9, code->w9, code->w12);
            code->str(code->x9, Xbyak_aarch64::ptr(code->x0, kStateR11Offset));
            code->ldr(code->w11, Xbyak_aarch64::ptr(code->x0, kStateR12Offset));
            code->and_(code->w11, code->w11, code->w12);
            code->str(code->x11, Xbyak_aarch64::ptr(code->x0, kStateR12Offset));
            code->ldr(code->w13, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            code->orr(code->w10, code->w10, code->w13);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRbxOffset));
            emit_inline_test32_flags(*code, code->w10);
            code->ldr(code->x12, Xbyak_aarch64::ptr(code->x0, kStateRdxOffset));
            code->lsl(code->x9, code->x9, 1);
            code->add(code->x12, code->x12, code->x9);
            code->ldrh(code->w13, Xbyak_aarch64::ptr(code->x12));
            code->str(code->x13, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));

            // Saturating blue sum, final word, ordered store, and loop control.
            code->add(code->w13, code->w13, code->w11);
            code->mov(code->w9, 0x1f);
            code->cmp(code->w13, code->w9);
            code->bls(blue_done);
            code->ldr(code->w13, Xbyak_aarch64::ptr(code->x0, kStateRbpOffset));
            code->L(blue_done);
            code->ldr(code->w10, Xbyak_aarch64::ptr(code->x0, kStateRbxOffset));
            code->orr(code->w13, code->w13, code->w10);
            code->str(code->x13, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            emit_inline_test32_flags(*code, code->w13);
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x0, kStateRsiOffset));
            code->strh(code->w13, Xbyak_aarch64::ptr(code->x9));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRcxOffset));
            code->add(code->x10, code->x10, 1);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRcxOffset));
            code->add(code->x9, code->x9, 2);
            code->str(code->x9, Xbyak_aarch64::ptr(code->x0, kStateRsiOffset));
            code->ldr(code->w11, Xbyak_aarch64::ptr(code->x0, kStateR8Offset));
            emit_inline_test32_flags(*code, code->w11);
            code->cbnz(code->w11, take);
            code->mov(code->x0, fallthrough);
            code->ret();
            code->L(take);
            code->mov(code->x0, taken);
            code->ret();
            code->ready();
            auto* entry = CommitCode(std::move(code));
            return finish_direct_native(entry);
        }
    }

    // Sonic's second steady-state RGB565 combiner.  Unlike the saturating loop above this
    // variant adds three pre-expanded channel tables and keeps the 16-bit x86 partial-register
    // writes visible between lookups.  It was the next hottest individual gameplay helper
    // (BHELPER_80021da5a_sz_6b_n_28).  Match the complete shape, derive the sole RIP-relative
    // qword address from the decoded instruction, and publish the exact IR before every guest
    // load/store so synchronous faults retain interpreter RIP and already-committed state.
    static constexpr std::array<std::uint8_t, 107> kRgb565TableBlendJnePattern = {
        0x4c, 0x89, 0xc0, 0x44, 0x0f, 0xb7, 0x1f, 0x48,
        0xc1, 0xe0, 0x09, 0x48, 0x03, 0x05, 0x6c, 0xa9,
        0x0f, 0x00, 0xc4, 0xc2, 0x10, 0xf7, 0xeb, 0x4d,
        0x89, 0xd9, 0x0f, 0xb7, 0x1c, 0x58, 0x66, 0x41,
        0x8b, 0x2c, 0x6e, 0x41, 0x83, 0xe3, 0x1f, 0x49,
        0xc1, 0xe9, 0x0b, 0x66, 0x43, 0x8b, 0x14, 0x4e,
        0x48, 0x89, 0xd8, 0x48, 0xc1, 0xe8, 0x0b, 0x66,
        0x41, 0x03, 0x14, 0x44, 0xc4, 0xe2, 0x10, 0xf7,
        0xc3, 0x83, 0xe3, 0x1f, 0x66, 0x41, 0x03, 0x2c,
        0x44, 0x66, 0x43, 0x8b, 0x04, 0x5e, 0xc1, 0xe2,
        0x0b, 0x66, 0x41, 0x03, 0x04, 0x5c, 0xc1, 0xe5,
        0x06, 0x09, 0xd5, 0x09, 0xe8, 0x66, 0x89, 0x07,
        0x48, 0xff, 0xc1, 0x48, 0x83, 0xc7, 0x02, 0x85,
        0xf6, 0x75, 0x8b,
    };
    if (block_bytes_match(kRgb565TableBlendJnePattern.data(),
                          kRgb565TableBlendJnePattern.size()) &&
        block.instructions.size() == 28) {
        const LsxDecodedOp& rip_add = block.instructions[3];
        const LsxDecodedOp& terminator = block.instructions.back();
        std::uint64_t taken = 0;
        if (rip_add.operand_count >= 2 &&
            rip_add.operands[1].type == X86_OPERAND_TYPE_MEMORY &&
            rip_add.operands[1].mem.base == X86_REGISTER_RIP &&
            TryResolveBranchTarget(terminator, taken)) {
            const std::uint64_t texture_base_qword =
                rip_add.guest_rip + rip_add.length +
                static_cast<std::uint64_t>(
                    SignedMemoryDisplacement(rip_add.operands[1]));
            const std::uint64_t fallthrough = terminator.guest_rip + terminator.length;
            auto code = std::make_unique<Xbyak_aarch64::CodeGenerator>(32768);

            const auto emit_publish_fault_ir = [&](const std::size_t index) {
                const LsxDecodedOp& ir = block.instructions[index];
                code->mov(code->x17, ir.guest_rip);
                code->str(code->x17,
                          Xbyak_aarch64::ptr(code->x19, kStateRipOffset));
                EmitJitRelocatablePointer(
                    *code, code->x17, reinterpret_cast<std::uint64_t>(&ir));
                code->str(code->x17, Xbyak_aarch64::ptr(code->x21));
            };
            const auto emit_return = [&](const std::uint64_t target) {
                code->mov(code->x9, 0);
                code->str(code->x9, Xbyak_aarch64::ptr(code->x21));
                code->mov(code->x0, target);
                code->ldp(code->x21, code->x22,
                          Xbyak_aarch64::ptr(code->sp, 32));
                code->ldp(code->x19, code->x20,
                          Xbyak_aarch64::ptr(code->sp, 16));
                code->ldp(code->x29, code->x30,
                          Xbyak_aarch64::post_ptr(code->sp, 48));
                code->ret();
            };
            const auto emit_logic64_flags = [&](const XReg& value) {
                code->mov(code->w14, WReg(value.getIdx()));
                code->lsr(code->w15, code->w14, 4);
                code->eor(code->w14, code->w14, code->w15);
                code->lsr(code->w15, code->w14, 2);
                code->eor(code->w14, code->w14, code->w15);
                code->lsr(code->w15, code->w14, 1);
                code->eor(code->w14, code->w14, code->w15);
                code->mov(code->w15, 1);
                code->and_(code->w14, code->w14, code->w15);
                code->eor(code->w14, code->w14, code->w15);
                code->lsl(code->x14, code->x14, kPfBit);
                code->lsr(code->x15, value, 63);
                code->lsl(code->x15, code->x15, kSfBit);
                code->orr(code->x14, code->x14, code->x15);
                code->cmp(value, 0);
                code->cset(code->x15, Xbyak_aarch64::EQ);
                code->lsl(code->x15, code->x15, kZfBit);
                code->orr(code->x14, code->x14, code->x15);
                code->ldr(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
                code->mov(code->x16, kArithmeticStatusBits);
                code->bic(code->x15, code->x15, code->x16);
                code->orr(code->x15, code->x15, code->x14);
                code->str(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
            };
            const auto emit_shl64_flags = [&](const XReg& lhs, const XReg& result,
                                               const std::uint32_t count) {
                code->lsl(result, lhs, count);
                emit_logic64_flags(result);
                code->lsr(code->x14, lhs, 64u - count);
                code->mov(code->x15, 1);
                code->and_(code->x14, code->x14, code->x15);
                code->ldr(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
                code->orr(code->x15, code->x15, code->x14);
                code->str(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
            };
            const auto emit_shl32_flags = [&](const WReg& lhs, const WReg& result,
                                               const std::uint32_t count) {
                code->lsl(result, lhs, count);
                emit_inline_test32_flags(*code, result);
                code->lsr(code->w14, lhs, 32u - count);
                code->mov(code->w15, 1);
                code->and_(code->w14, code->w14, code->w15);
                code->ldr(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
                code->orr(code->x15, code->x15, code->x14);
                code->str(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
            };
            const auto emit_add16_flags = [&](const WReg& lhs, const WReg& rhs,
                                               const WReg& result) {
                // Inputs are zero-extended words.  Keep the unmasked sum long enough to recover
                // bit 16 (x86 CF), then build the remaining five arithmetic flags at width 16.
                code->add(result, lhs, rhs);
                code->lsr(code->w14, result, 16);
                code->mov(code->w15, 1);
                code->and_(code->w14, code->w14, code->w15);
                code->uxth(result, result);

                code->cmp(result, 0);
                code->cset(code->x15, Xbyak_aarch64::EQ);
                code->lsl(code->x15, code->x15, kZfBit);
                code->orr(code->x14, code->x14, code->x15);
                code->lsr(code->w15, result, 15);
                code->mov(code->w16, 1);
                code->and_(code->w15, code->w15, code->w16);
                code->lsl(code->x15, code->x15, kSfBit);
                code->orr(code->x14, code->x14, code->x15);

                code->mov(code->w15, result);
                code->lsr(code->w16, code->w15, 4);
                code->eor(code->w15, code->w15, code->w16);
                code->lsr(code->w16, code->w15, 2);
                code->eor(code->w15, code->w15, code->w16);
                code->lsr(code->w16, code->w15, 1);
                code->eor(code->w15, code->w15, code->w16);
                code->mov(code->w16, 1);
                code->and_(code->w15, code->w15, code->w16);
                code->eor(code->w15, code->w15, code->w16);
                code->lsl(code->x15, code->x15, kPfBit);
                code->orr(code->x14, code->x14, code->x15);

                code->eor(code->w15, lhs, rhs);
                code->mvn(code->w15, code->w15);
                code->eor(code->w16, lhs, result);
                code->and_(code->w15, code->w15, code->w16);
                code->lsr(code->w15, code->w15, 15);
                code->mov(code->w16, 1);
                code->and_(code->w15, code->w15, code->w16);
                code->lsl(code->x15, code->x15, kOfBit);
                code->orr(code->x14, code->x14, code->x15);

                code->eor(code->w15, lhs, rhs);
                code->eor(code->w15, code->w15, result);
                code->lsr(code->w15, code->w15, 4);
                code->mov(code->w16, 1);
                code->and_(code->w15, code->w15, code->w16);
                code->lsl(code->x15, code->x15, kAfBit);
                code->orr(code->x14, code->x14, code->x15);

                code->ldr(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
                code->mov(code->x16, kArithmeticStatusBits);
                code->bic(code->x15, code->x15, code->x16);
                code->orr(code->x15, code->x15, code->x14);
                code->str(code->x15,
                          Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
            };
            const auto emit_bextr32 = [&](const WReg& value, const WReg& control,
                                           const WReg& result) {
                Xbyak_aarch64::Label zero;
                Xbyak_aarch64::Label length_ready;
                Xbyak_aarch64::Label full_mask;
                Xbyak_aarch64::Label mask_ready;
                Xbyak_aarch64::Label done;
                code->mov(code->w10, control);
                code->mov(code->w9, value);
                code->mov(code->w11, result);
                code->and_(code->w12, code->w10, 0xff);
                code->ubfx(code->w13, code->w10, 8, 8);
                code->cmp(code->w12, 32);
                code->bge(zero);
                code->cbz(code->w13, zero);
                code->mov(code->w10, 32);
                code->sub(code->w10, code->w10, code->w12);
                code->cmp(code->w13, code->w10);
                code->bls(length_ready);
                code->mov(code->w13, code->w10);
                code->L(length_ready);
                code->lsrv(code->w11, code->w9, code->w12);
                code->cmp(code->w13, 32);
                code->beq(full_mask);
                code->mov(code->w10, 1);
                code->lslv(code->w10, code->w10, code->w13);
                code->sub(code->w10, code->w10, 1);
                code->b(mask_ready);
                code->L(full_mask);
                code->mov(code->w10, 0xffffffffu);
                code->L(mask_ready);
                code->and_(code->w11, code->w11, code->w10);
                code->b(done);
                code->L(zero);
                code->mov(code->w11, 0);
                code->L(done);
                code->mov(result, code->w11);
                emit_inline_test32_flags(*code, result);
            };

            code->stp(code->x29, code->x30,
                      Xbyak_aarch64::pre_ptr(code->sp, -48));
            code->stp(code->x19, code->x20,
                      Xbyak_aarch64::ptr(code->sp, 16));
            code->stp(code->x21, code->x22,
                      Xbyak_aarch64::ptr(code->sp, 32));
            code->mov(code->x29, code->sp);
            code->mov(code->x19, code->x0);
            Xbyak_aarch64::Label fault_slot_ready;
            code->ldr(code->x21,
                      Xbyak_aarch64::ptr(code->x19, kStateFaultIrSlotOffset));
            code->cbnz(code->x21, fault_slot_ready);
            code->mov(code->x0, code->x19);
            EmitJitRelocatablePointer(
                *code, code->x16,
                reinterpret_cast<std::uint64_t>(
                    &PrepareGenericNativeMemoryFaultContext));
            code->blr(code->x16);
            code->mov(code->x21, code->x0);
            code->L(fault_slot_ready);
            code->mov(code->x0, code->x19);

            // mov rax,r8 ; movzx r11d,word [rdi]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR8Offset));
            code->str(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRdiOffset));
            emit_publish_fault_ir(1);
            code->ldrh(code->w11, Xbyak_aarch64::ptr(code->x10));
            code->str(code->x11, Xbyak_aarch64::ptr(code->x19, kStateR11Offset));

            // shl rax,9 ; add rax,[rip+disp32]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            emit_shl64_flags(code->x9, code->x10, 9);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            code->mov(code->x11, texture_base_qword);
            emit_publish_fault_ir(3);
            code->ldr(code->x12, Xbyak_aarch64::ptr(code->x11));
            emit_inline_add64_flags(*code, code->x10, code->x12, code->x13);
            code->str(code->x13, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));

            // bextr ebp,r11d,r13d ; mov r9,r11
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateR11Offset));
            code->ldr(code->w10, Xbyak_aarch64::ptr(code->x19, kStateR13Offset));
            emit_bextr32(code->w9, code->w10, code->w11);
            code->str(code->x11, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR11Offset));
            code->str(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR9Offset));

            // movzx ebx,word [rax+rbx*2]
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            code->ldr(code->x11, Xbyak_aarch64::ptr(code->x19, kStateRbxOffset));
            code->lsl(code->x11, code->x11, 1);
            code->add(code->x10, code->x10, code->x11);
            emit_publish_fault_ir(6);
            code->ldrh(code->w12, Xbyak_aarch64::ptr(code->x10));
            code->str(code->x12, Xbyak_aarch64::ptr(code->x19, kStateRbxOffset));

            // mov bp,word [r14+rbp*2]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR14Offset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
            code->lsl(code->x10, code->x10, 1);
            code->add(code->x9, code->x9, code->x10);
            emit_publish_fault_ir(7);
            code->ldrh(code->w11, Xbyak_aarch64::ptr(code->x9));
            code->strh(code->w11, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));

            // and r11d,0x1f ; shr r9,11
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateR11Offset));
            code->mov(code->w10, 0x1f);
            code->and_(code->w9, code->w9, code->w10);
            code->str(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR11Offset));
            emit_inline_test32_flags(*code, code->w9);
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR9Offset));
            code->lsr(code->x10, code->x9, 11);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x19, kStateR9Offset));
            emit_logic64_flags(code->x10);
            code->lsr(code->x14, code->x9, 10);
            code->mov(code->x15, 1);
            code->and_(code->x14, code->x14, code->x15);
            code->ldr(code->x15, Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));
            code->orr(code->x15, code->x15, code->x14);
            code->str(code->x15, Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));

            // mov dx,word [r14+r9*2]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR14Offset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateR9Offset));
            code->lsl(code->x10, code->x10, 1);
            code->add(code->x9, code->x9, code->x10);
            emit_publish_fault_ir(10);
            code->ldrh(code->w11, Xbyak_aarch64::ptr(code->x9));
            code->strh(code->w11, Xbyak_aarch64::ptr(code->x19, kStateRdxOffset));

            // mov rax,rbx ; shr rax,11
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRbxOffset));
            code->str(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            code->lsr(code->x10, code->x9, 11);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            emit_logic64_flags(code->x10);
            code->lsr(code->x14, code->x9, 10);
            code->mov(code->x15, 1);
            code->and_(code->x14, code->x14, code->x15);
            code->ldr(code->x15, Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));
            code->orr(code->x15, code->x15, code->x14);
            code->str(code->x15, Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));

            // add dx,word [r12+rax*2]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR12Offset));
            code->lsl(code->x10, code->x10, 1);
            code->add(code->x9, code->x9, code->x10);
            emit_publish_fault_ir(13);
            code->ldrh(code->w10, Xbyak_aarch64::ptr(code->x9));
            code->ldrh(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRdxOffset));
            emit_add16_flags(code->w9, code->w10, code->w11);
            code->strh(code->w11, Xbyak_aarch64::ptr(code->x19, kStateRdxOffset));

            // bextr eax,ebx,r13d ; and ebx,0x1f
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRbxOffset));
            code->ldr(code->w10, Xbyak_aarch64::ptr(code->x19, kStateR13Offset));
            emit_bextr32(code->w9, code->w10, code->w11);
            code->str(code->x11, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRbxOffset));
            code->mov(code->w10, 0x1f);
            code->and_(code->w9, code->w9, code->w10);
            code->str(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRbxOffset));
            emit_inline_test32_flags(*code, code->w9);

            // add bp,word [r12+rax*2]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR12Offset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            code->lsl(code->x10, code->x10, 1);
            code->add(code->x9, code->x9, code->x10);
            emit_publish_fault_ir(16);
            code->ldrh(code->w10, Xbyak_aarch64::ptr(code->x9));
            code->ldrh(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
            emit_add16_flags(code->w9, code->w10, code->w11);
            code->strh(code->w11, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));

            // mov ax,word [r14+r11*2]
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR14Offset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateR11Offset));
            code->lsl(code->x10, code->x10, 1);
            code->add(code->x9, code->x9, code->x10);
            emit_publish_fault_ir(17);
            code->ldrh(code->w11, Xbyak_aarch64::ptr(code->x9));
            code->strh(code->w11, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));

            // shl edx,11 ; add ax,word [r12+rbx*2]
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRdxOffset));
            emit_shl32_flags(code->w9, code->w10, 11);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRdxOffset));
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateR12Offset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRbxOffset));
            code->lsl(code->x10, code->x10, 1);
            code->add(code->x9, code->x9, code->x10);
            emit_publish_fault_ir(19);
            code->ldrh(code->w10, Xbyak_aarch64::ptr(code->x9));
            code->ldrh(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            emit_add16_flags(code->w9, code->w10, code->w11);
            code->strh(code->w11, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));

            // shl ebp,6 ; or ebp,edx ; or eax,ebp
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
            emit_shl32_flags(code->w9, code->w10, 6);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
            code->ldr(code->w11, Xbyak_aarch64::ptr(code->x19, kStateRdxOffset));
            code->orr(code->w10, code->w10, code->w11);
            code->str(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
            emit_inline_test32_flags(*code, code->w10);
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            code->orr(code->w9, code->w9, code->w10);
            code->str(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRaxOffset));
            emit_inline_test32_flags(*code, code->w9);

            // mov word [rdi],ax
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x19, kStateRdiOffset));
            emit_publish_fault_ir(23);
            code->strh(code->w9, Xbyak_aarch64::ptr(code->x10));

            // inc rcx preserves CF; add rdi,2 then TEST ESI supplies the final branch flags.
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRcxOffset));
            code->ldr(code->x22, Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));
            code->mov(code->x10, 1);
            code->and_(code->x22, code->x22, code->x10);
            emit_inline_add64_flags(*code, code->x9, code->x10, code->x11);
            code->str(code->x11, Xbyak_aarch64::ptr(code->x19, kStateRcxOffset));
            code->ldr(code->x14, Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));
            code->mov(code->x15, ~std::uint64_t{1});
            code->and_(code->x14, code->x14, code->x15);
            code->orr(code->x14, code->x14, code->x22);
            code->str(code->x14, Xbyak_aarch64::ptr(code->x19, kStateRflagsOffset));
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x19, kStateRdiOffset));
            code->mov(code->x10, 2);
            emit_inline_add64_flags(*code, code->x9, code->x10, code->x11);
            code->str(code->x11, Xbyak_aarch64::ptr(code->x19, kStateRdiOffset));
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x19, kStateRsiOffset));
            emit_inline_test32_flags(*code, code->w9);

            Xbyak_aarch64::Label take;
            code->cbnz(code->w9, take);
            emit_return(fallthrough);
            code->L(take);
            emit_return(taken);
            code->ready();
            auto* entry = CommitCode(std::move(code));
            return finish_direct_native(entry);
        }
    }

    // Four compact RSDK iteration blocks account for another large slice of steady-state
    // gameplay helpers.  Keep these byte-shape based: the relative terminator supplies the
    // target and an identical block at any guest RIP is equally valid.  The two store-bearing
    // loops publish the last live arithmetic flags before the first potentially faulting store,
    // retain x86's partial-register rules, and preserve the original store order for aliasing.
    const auto emit_inline_sub64_flags = [&]
        (Xbyak_aarch64::CodeGenerator& code, const XReg& lhs, const XReg& rhs,
         const XReg& result) {
        code.subs(result, lhs, rhs);
        code.cset(code.x14, Xbyak_aarch64::CS);
        code.mov(code.x15, 1);
        code.eor(code.x14, code.x14, code.x15);
        code.cset(code.x15, Xbyak_aarch64::EQ);
        code.lsl(code.x15, code.x15, kZfBit);
        code.orr(code.x14, code.x14, code.x15);
        code.cset(code.x15, Xbyak_aarch64::MI);
        code.lsl(code.x15, code.x15, kSfBit);
        code.orr(code.x14, code.x14, code.x15);
        code.cset(code.x15, Xbyak_aarch64::VS);
        code.lsl(code.x15, code.x15, kOfBit);
        code.orr(code.x14, code.x14, code.x15);

        code.mov(code.w15, WReg(result.getIdx()));
        code.lsr(code.w16, code.w15, 4);
        code.eor(code.w15, code.w15, code.w16);
        code.lsr(code.w16, code.w15, 2);
        code.eor(code.w15, code.w15, code.w16);
        code.lsr(code.w16, code.w15, 1);
        code.eor(code.w15, code.w15, code.w16);
        code.mov(code.w16, 1);
        code.and_(code.w15, code.w15, code.w16);
        code.eor(code.w15, code.w15, code.w16);
        code.lsl(code.x15, code.x15, kPfBit);
        code.orr(code.x14, code.x14, code.x15);

        code.eor(code.x15, lhs, rhs);
        code.eor(code.x15, code.x15, result);
        code.lsr(code.x15, code.x15, 4);
        code.mov(code.x16, 1);
        code.and_(code.x15, code.x15, code.x16);
        code.lsl(code.x15, code.x15, kAfBit);
        code.orr(code.x14, code.x14, code.x15);

        code.ldr(code.x15, Xbyak_aarch64::ptr(code.x0, kStateRflagsOffset));
        code.mov(code.x16, kArithmeticStatusBits);
        code.bic(code.x15, code.x15, code.x16);
        code.orr(code.x15, code.x15, code.x14);
        code.str(code.x15, Xbyak_aarch64::ptr(code.x0, kStateRflagsOffset));
    };

    static constexpr std::array<std::uint8_t, 33> kR13RecordAdvanceJbPattern = {
        0x41, 0xff, 0xc5, 0x48, 0x05, 0x58, 0x08, 0x00,
        0x00, 0x41, 0x0f, 0xb7, 0xcd, 0x49, 0x89, 0x07,
        0x66, 0x45, 0x89, 0x6f, 0x26, 0x81, 0xf9, 0x40,
        0x09, 0x00, 0x00, 0x0f, 0x82, 0x6f, 0xfd, 0xff,
        0xff,
    };
    if (block_bytes_match(kR13RecordAdvanceJbPattern.data(),
                          kR13RecordAdvanceJbPattern.size())) {
        const LsxDecodedOp& terminator = block.instructions.back();
        std::uint64_t taken = 0;
        if (TryResolveBranchTarget(terminator, taken)) {
            const std::uint64_t fallthrough = terminator.guest_rip + terminator.length;
            auto code = std::make_unique<Xbyak_aarch64::CodeGenerator>(4096);
            Xbyak_aarch64::Label take;
            code->ldr(code->w9, Xbyak_aarch64::ptr(code->x0, kStateR13Offset));
            code->add(code->w9, code->w9, 1);
            code->str(code->x9, Xbyak_aarch64::ptr(code->x0, kStateR13Offset));
            code->ldr(code->x10, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            code->mov(code->x12, 0x858);
            emit_inline_add64_flags(*code, code->x10, code->x12, code->x11);
            code->str(code->x11, Xbyak_aarch64::ptr(code->x0, kStateRaxOffset));
            code->uxth(code->w12, code->w9);
            code->str(code->x12, Xbyak_aarch64::ptr(code->x0, kStateRcxOffset));
            code->ldr(code->x13, Xbyak_aarch64::ptr(code->x0, kStateR15Offset));
            code->str(code->x11, Xbyak_aarch64::ptr(code->x13));
            code->strh(code->w9, Xbyak_aarch64::ptr(code->x13, 0x26));
            code->mov(code->w10, 0x940);
            emit_inline_sub32_flags(*code, code->w12, code->w10, code->w11);
            code->ldr(code->x9, Xbyak_aarch64::ptr(code->x0, kStateRflagsOffset));
            code->tbnz(code->x9, kCfBit, take);
            code->mov(code->x0, fallthrough);
            code->ret();
            code->L(take);
            code->mov(code->x0, taken);
            code->ret();
            code->ready();
            auto* entry = CommitCode(std::move(code));
            return finish_direct_native(entry);
        }
    }

