                        const bool vex = IsVexPackedCompareMnemonic(mnemonic);
                        const bool greater = PackedCompareSignedGreaterThan(mnemonic);
                        const std::size_t element_bytes =
                            PackedCompareElementBytes(mnemonic);
                        const std::uint8_t lhs_index = vex ? 1u : 0u;
                        const std::uint8_t rhs_index = vex ? 2u : 1u;
                        std::uint32_t lhs_width = 0;
                        std::uint32_t rhs_width = 0;
                        emitted = emit_vector_load_pair(ir, ir.operands[lhs_index],
                                                        code->q0, code->q1, lhs_width) &&
                                  emit_vector_load_pair(ir, ir.operands[rhs_index],
                                                        code->q2, code->q3, rhs_width) &&
                                  lhs_width == rhs_width &&
                                  (lhs_width == 16 || lhs_width == 32);
                        if (!emitted) {
                            continue;
                        }
                        const auto emit_compare = [&](const VReg& output,
                                                      const VReg& lhs,
                                                      const VReg& rhs) {
                            if (element_bytes == 1) {
                                if (greater) code->cmgt(VReg16B{output.getIdx()},
                                                       VReg16B{lhs.getIdx()},
                                                       VReg16B{rhs.getIdx()});
                                else code->cmeq(VReg16B{output.getIdx()},
                                                VReg16B{lhs.getIdx()},
                                                VReg16B{rhs.getIdx()});
                            } else if (element_bytes == 2) {
                                if (greater) code->cmgt(VReg8H{output.getIdx()},
                                                       VReg8H{lhs.getIdx()},
                                                       VReg8H{rhs.getIdx()});
                                else code->cmeq(VReg8H{output.getIdx()},
                                                VReg8H{lhs.getIdx()},
                                                VReg8H{rhs.getIdx()});
                            } else if (element_bytes == 4) {
                                if (greater) code->cmgt(VReg4S{output.getIdx()},
                                                       VReg4S{lhs.getIdx()},
                                                       VReg4S{rhs.getIdx()});
                                else code->cmeq(VReg4S{output.getIdx()},
                                                VReg4S{lhs.getIdx()},
                                                VReg4S{rhs.getIdx()});
                            } else {
                                if (greater) code->cmgt(VReg2D{output.getIdx()},
                                                       VReg2D{lhs.getIdx()},
                                                       VReg2D{rhs.getIdx()});
                                else code->cmeq(VReg2D{output.getIdx()},
                                                VReg2D{lhs.getIdx()},
                                                VReg2D{rhs.getIdx()});
                            }
                        };
                        emit_compare(code->v4, code->v0, code->v2);
                        if (lhs_width == 32) {
                            emit_compare(code->v5, code->v1, code->v3);
                        }
                        emitted = emit_vector_store_pair(ir, ir.operands[0], code->q4,
                                                         code->q5, lhs_width);
