                        const std::uint8_t value_index = vex ? 2u : 1u;
                        const std::uint8_t immediate_index = vex ? 3u : 2u;
                        std::uint32_t merge_width = 0;
                        emitted = emit_vector_load_pair(ir, ir.operands[merge_index],
                                                        code->q0, code->q1,
                                                        merge_width) &&
                                  merge_width == 16 &&
                                  emit_read_operand(ir, ir.operands[value_index],
                                                    code->x10);
