                        std::uint64_t table_high = 0;
                        std::memcpy(&table_low, table_indices.data(), sizeof(table_low));
                        std::memcpy(&table_high, table_indices.data() + 8,
                                    sizeof(table_high));
                        code->eor(code->v2.b16, code->v2.b16, code->v2.b16);
                        code->mov(code->x10, table_low);
                        code->ins(code->v2.d2[0], code->x10);
                        code->mov(code->x10, table_high);
                        code->ins(code->v2.d2[1], code->x10);
