                                        code->cmp(code->x14, code->x10);
                                        code->blo(direct_exchange);
                                        code->mov(code->x11, image_hi + 0x30000000ull);
                                        code->cmp(code->x14, code->x11);
                                        code->bhs(direct_exchange);
                                        code->b(slow_exchange);
