                            emitted = emit_read_operand(ir, ir.operands[0], code->x10) &&
                                      emit_read_operand(ir, ir.operands[1], code->x11) &&
                                      emit_write_operand(ir, ir.operands[0], code->x11) &&
                                      emit_write_operand(ir, ir.operands[1], code->x10);
