                    case X86_MNEMONIC_LEAVE:
                        code->ldr(code->x10,
                                  Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
                        code->str(code->x10,
                                  Xbyak_aarch64::ptr(code->x19, kStateRspOffset));
                        emit_publish_fault_ir(ir);
                        code->ldr(code->x12, Xbyak_aarch64::ptr(code->x10));
                        code->add(code->x10, code->x10, 8);
                        code->str(code->x10,
                                  Xbyak_aarch64::ptr(code->x19, kStateRspOffset));
                        code->str(code->x12,
                                  Xbyak_aarch64::ptr(code->x19, kStateRbpOffset));
