bool IsLikelyGuestReadableForTrace(const std::uint64_t address) {
    // Keep this deliberately conservative. Low addresses such as 0xa0000 are
    // valid-looking integers in mono metadata but are not mapped process memory;
    // direct ReadMemory() on them is a host SIGSEGV, not a catchable C++ error.
    // Also reject the 32-bit 0x8xxxxxxx band: valid PS4 module VAs are in the
    // 0x8xxxxxxxx *nine-hex-digit* range, while 0x80000018-style values are
    // truncated sentinels/tokens seen in malformed metadata probes.
    if (address >= 0x20000000ull && address < 0x70000000ull) {
        return true;
    }
    return address >= 0x100000000ull && address < 0x900000000ull;
}

bool IsTraceReadableAddress(const std::uint64_t address, const std::uint64_t bytes = 1) {
    if (bytes == 0) {
        return true;
    }
    if (address == 0 || address > (~std::uint64_t{0} - (bytes - 1))) {
        return false;
    }
    if (!IsLikelyGuestReadableForTrace(address)) {
        return false;
    }
#ifdef __ANDROID__
    static const std::uint64_t page_size =
        static_cast<std::uint64_t>(::sysconf(_SC_PAGESIZE) > 0 ? ::sysconf(_SC_PAGESIZE) : 4096);
    const std::uint64_t page_mask = ~(page_size - 1);
    const std::uint64_t start = address & page_mask;
    const std::uint64_t end = (address + bytes + page_size - 1) & page_mask;
    if (end <= start) {
        return false;
    }
    const std::uint64_t page_count = (end - start) / page_size;
    if (page_count == 0 || page_count > 64) {
        return false;
    }
    std::array<unsigned char, 64> vec{};
    if (::mincore(reinterpret_cast<void*>(start), static_cast<std::size_t>(end - start), vec.data()) != 0) {
        return false;
    }
#endif
    return true;
}

bool ReadGuestBytesChecked(const std::uint64_t address, void* dst, const std::size_t size) {
    if (size == 0) {
        return true;
    }
    if (address == 0 || dst == nullptr || address > (~std::uint64_t{0} - (size - 1))) {
        return false;
    }
#ifdef __ANDROID__
    return g_jit_stable_guest_reads
               ? ExecutorJitReadGuestBytesStable(address, dst, size)
               : ExecutorJitReadGuestBytes(address, dst, size);
#else
    if (!IsTraceReadableAddress(address, size)) {
        return false;
    }
    std::memcpy(dst, reinterpret_cast<const void*>(address), size);
    return true;
#endif
}

bool WriteGuestBytesChecked(const std::uint64_t address, const void* src, const std::size_t size) {
    if (size == 0) {
        return true;
    }
    if (address == 0 || src == nullptr || address > (~std::uint64_t{0} - (size - 1))) {
        return false;
    }
    // Null-page guard: reject guest stores into the first 64 KiB (a guest null-pointer + field
    // offset, e.g. the RSDK audio worker's [null+0x4b0] SIGSEGV that killed the whole process
    // after the render came up). Real hardware/interpreter fault-handle a guest bad store rather
    // than aborting the emulator; skip the write so the offending guest thread continues instead
    // of crashing every other thread with it. All real guest regions live far above this.
    if (address < 0x10000ull) {
#ifdef __ANDROID__
        static std::atomic<unsigned> s_nullw_budget{0};
        const unsigned n = s_nullw_budget.fetch_add(1, std::memory_order_relaxed);
        if (n < 64) {
            JitLog("[EXECUTOR_JIT_NULLPAGE_STORE] addr=0x%llx size=%zu (skipped)",
                        static_cast<unsigned long long>(address), size);
        }
#endif
        return false;
    }
#ifdef __ANDROID__
    return ExecutorJitWriteGuestBytes(address, src, size);
#else
    if (!IsTraceReadableAddress(address, size)) {
        return false;
    }
    std::memcpy(reinterpret_cast<void*>(address), src, size);
    return true;
#endif
}

std::uint64_t TraceQwordOrZero(const std::uint64_t address) {
    if (!IsTraceReadableAddress(address, 8)) {
        return 0;
    }
    return ReadMemory(address, 8);
}

bool IsPlausibleHleGuestReturn(const std::uint64_t target) {
    if (target == 0 || target == kGuestExitSentinel ||
        (target & 0xffff000000000000ULL) == 0xcccc000000000000ULL) {
        return false;
    }

    // Positive code addresses stay executable for the life of a translated block. Cache only
    // positive validations: a negative address may become valid after lazy mapping/SMC, whereas a
    // previously decoded return RIP remains a safe plausibility result even if the block is later
    // invalidated and recompiled.
    struct ReturnRipEntry {
        std::uint64_t target = 0;
    };
    static thread_local std::array<ReturnRipEntry, 512> return_rip_cache{};
    constexpr std::uint64_t GoldenRatio = 0x9e3779b97f4a7c15ull;
    const std::size_t cache_slot =
        static_cast<std::size_t>(((target ^ (target >> 33u)) * GoldenRatio) >> (64u - 9u));
    if (return_rip_cache[cache_slot].target == target) {
        return true;
    }

    std::array<std::uint8_t, X86_MAX_INSTRUCTION_LENGTH> bytes{};
    if (!ReadGuestBytesChecked(target, bytes.data(), bytes.size())) {
        return false;
    }
    bool all_cc = true;
    for (const auto byte : bytes) {
        all_cc = all_cc && byte == 0xcc;
    }
    if (all_cc) {
        return false;
    }

    const bool valid = HasMachineInstruction(bytes);
    if (valid) {
        return_rip_cache[cache_slot].target = target;
    }
    return valid;
}

std::string TraceCStringOrEmpty(const std::uint64_t address, const std::size_t max_len = 47) {
    if (!IsTraceReadableAddress(address, 1)) {
        return {};
    }
    std::string out;
    out.reserve(max_len);
    try {
        for (std::size_t i = 0; i < max_len; ++i) {
            const std::uint8_t ch = static_cast<std::uint8_t>(ReadMemory(address + i, 1));
            if (ch == 0) {
                break;
            }
            out.push_back(std::isprint(ch) ? static_cast<char>(ch) : '.');
        }
    } catch (...) {
        if (out.empty()) {
            out = "<unreadable>";
        }
    }
    return out;
}

bool TraceReadQword(const std::uint64_t address, std::uint64_t& value) {
    if (!IsTraceReadableAddress(address, 8)) {
        return false;
    }
    try {
        value = ReadMemory(address, 8);
        return true;
    } catch (...) {
        return false;
    }
}

std::uint64_t TraceQwordSafe(const std::uint64_t address) {
    std::uint64_t value = 0;
    return TraceReadQword(address, value) ? value : 0;
}

std::uint16_t TraceWordSafe(const std::uint64_t address) {
    if (!IsTraceReadableAddress(address, 2)) {
        return 0;
    }
    try {
        return static_cast<std::uint16_t>(ReadMemory(address, 2));
    } catch (...) {
        return 0;
    }
}

std::uint32_t TraceDwordSafe(const std::uint64_t address) {
    if (!IsTraceReadableAddress(address, 4)) {
        return 0;
    }
    try {
        return static_cast<std::uint32_t>(ReadMemory(address, 4));
    } catch (...) {
        return 0;
    }
}

std::uint8_t TraceByteSafe(const std::uint64_t address) {
    if (!IsTraceReadableAddress(address, 1)) {
        return 0;
    }
    try {
        return static_cast<std::uint8_t>(ReadMemory(address, 1));
    } catch (...) {
        return 0;
    }
}

std::int32_t TraceI32Safe(const std::uint64_t address) {
    return static_cast<std::int32_t>(TraceDwordSafe(address));
}











std::uint64_t ResolveDynamicTarget(LsxMachineImage& state, const LsxDecodedOp& ir) {
    if (ir.operand_count == 0) {
        return 0;
    }
    std::uint64_t static_target = 0;
    if (TryResolveBranchTarget(ir, static_target)) {
        return static_target;
    }
    return LoadOperandValue(state, ir.decoded, ir.operands[0], false);
}

bool IsCmovMnemonic(const X86Mnemonic mnemonic) {
    // Decoder mnemonic IDs are opaque.  In particular, iced-x86 exposes the
    // Z/NZ spellings as aliases of E/NE, so an ordinal CMOVB..CMOVZ range
    // excludes valid conditions such as CMOVNE.
    switch (mnemonic) {
    case X86_MNEMONIC_CMOVA:
    case X86_MNEMONIC_CMOVAE:
    case X86_MNEMONIC_CMOVB:
    case X86_MNEMONIC_CMOVBE:
    case X86_MNEMONIC_CMOVE:
    case X86_MNEMONIC_CMOVG:
    case X86_MNEMONIC_CMOVGE:
    case X86_MNEMONIC_CMOVL:
    case X86_MNEMONIC_CMOVLE:
    case X86_MNEMONIC_CMOVNE:
    case X86_MNEMONIC_CMOVNO:
    case X86_MNEMONIC_CMOVNP:
    case X86_MNEMONIC_CMOVNS:
    case X86_MNEMONIC_CMOVO:
    case X86_MNEMONIC_CMOVP:
    case X86_MNEMONIC_CMOVS:
        return true;
    default:
        return false;
    }
}

bool IsSetccMnemonic(const X86Mnemonic mnemonic) {
    switch (mnemonic) {
    case X86_MNEMONIC_SETA:
    case X86_MNEMONIC_SETAE:
    case X86_MNEMONIC_SETB:
    case X86_MNEMONIC_SETBE:
    case X86_MNEMONIC_SETE:
    case X86_MNEMONIC_SETG:
    case X86_MNEMONIC_SETGE:
    case X86_MNEMONIC_SETL:
    case X86_MNEMONIC_SETLE:
    case X86_MNEMONIC_SETNE:
    case X86_MNEMONIC_SETNO:
    case X86_MNEMONIC_SETNP:
    case X86_MNEMONIC_SETNS:
    case X86_MNEMONIC_SETO:
    case X86_MNEMONIC_SETP:
    case X86_MNEMONIC_SETS:
        return true;
    default:
        return false;
    }
}

bool TryGetRegisterStateOffset(const LsxOperandRecord& operand, std::size_t& state_offset) {
    if (operand.type != X86_OPERAND_TYPE_REGISTER) {
        return false;
    }
    DecodedGpr reg{};
    if (!DecodeGprRegister(operand.reg.value, reg) || reg.high8) {
        return false;
    }
    state_offset = offsetof(LsxMachineImage, gpr) + (PhysicalGprIndex(reg.reg) * sizeof(std::uint64_t));
    return true;
}

bool CanUseStateLaneOrMemory(const LsxOperandRecord& operand) {
    if (operand.type == X86_OPERAND_TYPE_MEMORY) {
        return true;
    }
    std::size_t ignored = 0;
    return TryGetRegisterStateOffset(operand, ignored);
}

bool CanExecuteImulInstruction(const LsxDecodedOp& ir) {
    if (ir.operand_count == 1) {
        return true;
    }
    if (ir.operand_count >= 2) {
        std::size_t ignored = 0;
        return TryGetRegisterStateOffset(ir.operands[0], ignored);
    }
    return false;
}

void Push64(LsxMachineImage& state, const std::uint64_t value) {
    const std::uint64_t rsp = GetGpr64(state, LsxGpr::Rsp) - 8;
    SetGpr64(state, LsxGpr::Rsp, rsp);
    WriteMemory(rsp, value, 8);
}

void PushSized(LsxMachineImage& state, const std::uint64_t value, const std::uint32_t size_bits) {
    const std::uint64_t size_bytes = size_bits <= 16 ? 2 : size_bits <= 32 ? 4 : 8;
    const std::uint64_t rsp = GetGpr64(state, LsxGpr::Rsp) - size_bytes;
    SetGpr64(state, LsxGpr::Rsp, rsp);
    WriteMemory(rsp, value, size_bytes);
}

std::uint64_t Pop64(LsxMachineImage& state) {
    const std::uint64_t rsp = GetGpr64(state, LsxGpr::Rsp);
    const std::uint64_t value = ReadMemory(rsp, 8);
    SetGpr64(state, LsxGpr::Rsp, rsp + 8);
    return value;
}










std::uint64_t PopSized(LsxMachineImage& state, const std::uint32_t size_bits) {
    const std::uint64_t size_bytes = size_bits <= 16 ? 2 : size_bits <= 32 ? 4 : 8;
    const std::uint64_t rsp = GetGpr64(state, LsxGpr::Rsp);
    const std::uint64_t value = ReadMemory(rsp, size_bytes);
    SetGpr64(state, LsxGpr::Rsp, rsp + size_bytes);
    return value;
}

bool TryDecodeXmmRegister(const LsxRegisterCode zreg, std::size_t& index) {
    if (zreg >= X86_REGISTER_XMM0 && zreg <= X86_REGISTER_XMM15) {
        index = static_cast<std::size_t>(zreg - X86_REGISTER_XMM0);
        return true;
    }
    if (zreg >= X86_REGISTER_YMM0 && zreg <= X86_REGISTER_YMM15) {
        index = static_cast<std::size_t>(zreg - X86_REGISTER_YMM0);
        return true;
    }
    return false;
}

bool IsXmmOperand(const LsxOperandRecord& operand) {
    std::size_t ignored = 0;
    return operand.type == X86_OPERAND_TYPE_REGISTER &&
           TryDecodeXmmRegister(operand.reg.value, ignored);
}

std::uint8_t* XmmLane(LsxMachineImage& state, const std::size_t index) {
    if (index >= kXmmRegisterCount) {
        return nullptr;
    }
    return reinterpret_cast<std::uint8_t*>(&state) + kXmmStateOffset +
           (index * kXmmRegisterBytes);
}

const std::uint8_t* XmmLane(const LsxMachineImage& state, const std::size_t index) {
    if (index >= kXmmRegisterCount) {
        return nullptr;
    }
    return reinterpret_cast<const std::uint8_t*>(&state) + kXmmStateOffset +
           (index * kXmmRegisterBytes);
}

std::size_t VectorOperandBytes(const LsxOperandRecord& operand) {
    if (operand.type == X86_OPERAND_TYPE_REGISTER && operand.reg.value >= X86_REGISTER_YMM0 &&
        operand.reg.value <= X86_REGISTER_YMM15) {
        return 32;
    }
    if (operand.size > 128) {
        return 32;
    }
    return 16;
}

bool VectorWriteZerosUpper(const DecodeSummary& instruction) {
    return instruction.encoding == X86_INSTRUCTION_ENCODING_VEX ||
           instruction.encoding == X86_INSTRUCTION_ENCODING_EVEX ||
           instruction.encoding == X86_INSTRUCTION_ENCODING_MVEX ||
           instruction.encoding == X86_INSTRUCTION_ENCODING_XOP;
}

bool ReadVector128(const LsxMachineImage& state, const DecodeSummary& instruction,
                   const LsxOperandRecord& operand,
                   std::array<std::uint8_t, kXmmRegisterBytes>& out) {
    out.fill(0);
    const std::size_t width = VectorOperandBytes(operand);
    if (operand.type == X86_OPERAND_TYPE_REGISTER) {
        std::size_t index = 0;
        if (!TryDecodeXmmRegister(operand.reg.value, index)) {
            return false;
        }
        const auto* lane = XmmLane(state, index);
        if (lane == nullptr) {
            return false;
        }
        std::memcpy(out.data(), lane, width);
        return true;
    }
    if (operand.type == X86_OPERAND_TYPE_MEMORY) {
        ReadMemoryBytes(CalculateMemoryAddress(state, instruction, operand), out.data(),
                        static_cast<std::uint32_t>(width));
        return true;
    }
    return false;
}

bool ReadScalar32(const LsxMachineImage& state, const DecodeSummary& instruction,
                  const LsxOperandRecord& operand, std::uint32_t& out) {
    if (operand.type == X86_OPERAND_TYPE_REGISTER) {
        std::size_t index = 0;
        if (TryDecodeXmmRegister(operand.reg.value, index)) {
            const auto* lane = XmmLane(state, index);
            if (lane == nullptr) {
                return false;
            }
            out = LoadUnaligned<std::uint32_t>(lane);
            return true;
        }
    }
    if (operand.type == X86_OPERAND_TYPE_MEMORY) {
        out = static_cast<std::uint32_t>(ReadMemory(CalculateMemoryAddress(state, instruction, operand), 4));
        return true;
    }
    return false;
}

bool WriteScalar32(LsxMachineImage& state, const DecodeSummary& instruction,
                   const LsxOperandRecord& operand, const std::uint32_t value) {
    if (operand.type == X86_OPERAND_TYPE_REGISTER) {
        std::size_t index = 0;
        if (!TryDecodeXmmRegister(operand.reg.value, index)) {
            return false;
        }
        auto* lane = XmmLane(state, index);
        if (lane == nullptr) {
            return false;
        }
        StoreUnaligned<std::uint32_t>(lane, value);
        return true;
    }
    if (operand.type == X86_OPERAND_TYPE_MEMORY) {
        WriteMemory(CalculateMemoryAddress(state, instruction, operand), value, 4);
        return true;
    }
    return false;
}

bool ReadScalar64(const LsxMachineImage& state, const DecodeSummary& instruction,
                  const LsxOperandRecord& operand, std::uint64_t& out) {
    if (operand.type == X86_OPERAND_TYPE_REGISTER) {
        std::size_t index = 0;
        if (TryDecodeXmmRegister(operand.reg.value, index)) {
            const auto* lane = XmmLane(state, index);
            if (lane == nullptr) {
                return false;
            }
            out = LoadUnaligned<std::uint64_t>(lane);
            return true;
        }
    }
    if (operand.type == X86_OPERAND_TYPE_MEMORY) {
        out = ReadMemory(CalculateMemoryAddress(state, instruction, operand), 8);
        return true;
    }
    return false;
}

bool WriteVector128(LsxMachineImage& state, const DecodeSummary& instruction,
                    const LsxOperandRecord& operand,
                    const std::array<std::uint8_t, kXmmRegisterBytes>& value) {
    const std::size_t width = VectorOperandBytes(operand);
    if (operand.type == X86_OPERAND_TYPE_REGISTER) {
        std::size_t index = 0;
        if (!TryDecodeXmmRegister(operand.reg.value, index)) {
            return false;
        }
        auto* lane = XmmLane(state, index);
        if (lane == nullptr) {
            return false;
        }
        std::memcpy(lane, value.data(), width);
        if (width < kXmmRegisterBytes && VectorWriteZerosUpper(instruction)) {
            std::memset(lane + width, 0, kXmmRegisterBytes - width);
        }
        return true;
    }
    if (operand.type == X86_OPERAND_TYPE_MEMORY) {
        WriteMemoryBytes(CalculateMemoryAddress(state, instruction, operand), value.data(),
                         static_cast<std::uint32_t>(width));
        return true;
    }
    return false;
}

bool IsGprOrMemoryOperand(const LsxOperandRecord& operand) {
    if (operand.type == X86_OPERAND_TYPE_MEMORY) {
        return true;
    }
    DecodedGpr ignored{};
    return operand.type == X86_OPERAND_TYPE_REGISTER &&
           DecodeGprRegister(operand.reg.value, ignored);
}

