bool IsStringCmpsInstruction(const LsxDecodedOp& ir) {
    if (ir.length == 0) {
        return false;
    }
    const auto mnemonic = static_cast<X86Mnemonic>(ir.mnemonic);
    const std::uint8_t opcode = ir.bytes[ir.length - 1];
    if (mnemonic == X86_MNEMONIC_CMPSB) {
        return opcode == 0xa6;
    }
    if (mnemonic == X86_MNEMONIC_CMPSW ||
        mnemonic == X86_MNEMONIC_CMPSD ||
        mnemonic == X86_MNEMONIC_CMPSQ) {
        return opcode == 0xa7;
    }
    return false;
}

