    case X86_MNEMONIC_VLDDQU:
    case X86_MNEMONIC_MOVNTDQ:
    case X86_MNEMONIC_VMOVNTDQ:
    case X86_MNEMONIC_VMOVNTDQA:
    case X86_MNEMONIC_MOVLPS:
    case X86_MNEMONIC_MOVHPS:
    case X86_MNEMONIC_MOVLPD:
    case X86_MNEMONIC_MOVHPD:
    case X86_MNEMONIC_VMOVLPS:
    case X86_MNEMONIC_VMOVHPS:
    case X86_MNEMONIC_VMOVLPD:
    case X86_MNEMONIC_VMOVHPD:
    case X86_MNEMONIC_MOVD:
