    case X86_MNEMONIC_ORPS:
    case X86_MNEMONIC_ORPD:
    case X86_MNEMONIC_VXORPS:
    case X86_MNEMONIC_VXORPD:
    case X86_MNEMONIC_XORPS:
    case X86_MNEMONIC_XORPD:
    case X86_MNEMONIC_PAND:
