    case X86_MNEMONIC_VMAXSD:
    case X86_MNEMONIC_CVTSI2SS:
    case X86_MNEMONIC_VCVTSI2SS:
    case X86_MNEMONIC_CVTSI2SD:
    case X86_MNEMONIC_VCVTSI2SD:
    case X86_MNEMONIC_CVTSS2SD:
    case X86_MNEMONIC_VCVTSS2SD:
    case X86_MNEMONIC_CVTSD2SS:
    case X86_MNEMONIC_VCVTSD2SS:
    case X86_MNEMONIC_CVTTSS2SI:
    case X86_MNEMONIC_VCVTTSS2SI:
    case X86_MNEMONIC_CVTTSD2SI:
    case X86_MNEMONIC_VCVTTSD2SI:
    case X86_MNEMONIC_UCOMISS:
    case X86_MNEMONIC_VUCOMISS:
    case X86_MNEMONIC_UCOMISD:
    case X86_MNEMONIC_VUCOMISD:
