            const auto& lhs_operand = ir->operands[0];
            const auto& rhs_operand = ir->operands[1];
            const bool lhs_memory = lhs_operand.type == X86_OPERAND_TYPE_MEMORY;
            const bool rhs_memory = rhs_operand.type == X86_OPERAND_TYPE_MEMORY;
            const auto& memory_operand = lhs_memory ? lhs_operand : rhs_operand;
            const auto& register_operand = lhs_memory ? rhs_operand : lhs_operand;
            std::size_t register_state_offset = 0;
            if ((lhs_memory || rhs_memory) &&
                TryGetRegisterStateOffset(register_operand, register_state_offset)) {
                auto* target = reinterpret_cast<void*>(
                    CalculateMemoryAddress(*state, ir->decoded, memory_operand));
                // A memory XCHG is implicitly locked on x86 even without an explicit LOCK prefix.
                ExecuteJitXchgMem(*state, target, register_state_offset, memory_operand.size);
            } else {
                const auto execute_xchg = [&]() {
                    const std::uint64_t lhs =
                        LoadOperandValue(*state, ir->decoded, lhs_operand, false);
                    const std::uint64_t rhs =
                        LoadOperandValue(*state, ir->decoded, rhs_operand, false);
                    StoreOperandValue(*state, ir->decoded, lhs_operand, rhs, true);
                    StoreOperandValue(*state, ir->decoded, rhs_operand, lhs, true);
                };
                if (lhs_memory || rhs_memory) {
                    // Rare high-byte-register form. Keep its whole exchange indivisible with respect
                    // to other fallback locked operations; normal GPR forms use the host atomic path.
                    std::lock_guard lock{g_locked_memory_mutex};
                    execute_xchg();
                } else {
                    execute_xchg();
                }
            }
